/**
 * @summary Send a message to the Agent represented by a FEZI API key
 */
export const externalAgentChatBodyMessageMax = 12000;



export const ExternalAgentChatBody = zod.object({
  "message": zod.string().min(1).max(externalAgentChatBodyMessageMax),
  "conversationId": zod.string().optional()
})

export const ExternalAgentChatResponse = zod.object({
  "id": zod.string(),
  "messageId": zod.string(),
  "agentId": zod.string(),
  "appId": zod.enum(['claude', 'deepseek', 'gapgpt', 'openai', 'mistral']).optional(),
  "model": zod.string().optional(),
  "message": zod.string(),
  "creditsUsed": zod.number().int(),
  "conversationId": zod.string(),
  "media": zod.object({
  "type": zod.enum(['image', 'video']),
  "url": zod.string(),
  "mimeType": zod.string(),
  "model": zod.string(),
  "isPreview": zod.boolean(),
  "prompt": zod.string()
}).optional(),
  "handoff": zod.array(zod.object({
  "agentId": zod.string(),
  "status": zod.string(),
  "summary": zod.string()
}))
})


/**
 * Stateless MCP JSON-RPC 2.0 over POST. Send `Content-Type: application/json`
 * and `Accept: application/json, text/event-stream`. Initialize and ping
 * are public. Private tool listing and tool calls require an existing
 * FEZI Site API key in `Authorization: Bearer <SITE_API_KEY>`. Supported
 * tools are `fezi_site_models` and `fezi_site_chat`; generation retains the
 * key's Agent/model scope, rate limits, and API Credit balance. No API key
 * is accepted in a URL or query parameter.
 *
 * Initialize with protocol version `2025-03-26`, then send
 * `notifications/initialized`. Example endpoint:
 * `https://persiandarkhorse.com/api/mcp`.
 *
 * Example authorized request (provide the key via your client's secure
 * secret store):
 *
 * ```sh
 * curl -X POST 'https://persiandarkhorse.com/api/mcp' \
 *   -H "Authorization: Bearer ${FEZI_SITE_API_KEY}" \
 *   -H 'Content-Type: application/json' \
 *   -H 'Accept: application/json, text/event-stream' \
 *   --data '{"jsonrpc":"2.0","id":2,"method":"tools/list"}'
 * ```
 *
 * To generate, call `tools/call` with
 * `{"name":"fezi_site_chat","arguments":{"message":"Hello"}}`.
 * @summary FEZI Site API Streamable HTTP MCP endpoint
 */
export const McpRpcBody = zod.object({
  "jsonrpc": zod.literal("2.0"),
  "id": zod.union([zod.string(),zod.number(),zod.null()]).optional(),
  "method": zod.string(),
  "params": zod.record(zod.string(), zod.unknown()).optional()
})

export const McpRpcResponse = zod.record(zod.string(), zod.unknown())


/**
 * @summary Unsupported stateless MCP event stream
 */
export const GetFeziStreamableMcpResponse = zod.void()


/**
 * @summary Gracefully terminate an MCP session
 */
export const DeleteFeziStreamableMcpSessionResponse = zod.void()


